'use strict';
// ============================================================
//  Translations — interface strings
//  Order of every entry: en, id, es, fr, de, pt, ja
// ============================================================
const LANG_ORDER = ['en', 'id', 'es', 'fr', 'de', 'pt', 'ja'];
let LANG_I = 0;
const L = {};
function addL(obj) { Object.assign(L, obj); }
function t(key, params) {
  const e = L[key];
  let s = e ? (e[LANG_I] != null && e[LANG_I] !== '' ? e[LANG_I] : e[0]) : key;
  if (params) for (const k in params) s = s.split('{' + k + '}').join(params[k]);
  return s;
}
function setLang(code) {
  LANG_I = Math.max(0, LANG_ORDER.indexOf(code));
  document.documentElement.lang = code;
  document.body.classList.toggle('lang-ja', code === 'ja');
  if (code === 'ja' && !document.getElementById('font-ja')) {
    const l = document.createElement('link'); l.id = 'font-ja'; l.rel = 'stylesheet';
    l.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&display=swap';
    document.head.appendChild(l);
  }
}

